css:
.faq-list_component { display: flex; gap: 5rem; align-items: flex-start; }
.faq-list_header { flex: none; width: 25rem; display: flex; flex-direction: column; align-items: flex-start; gap: 1rem; }
.faq-list_list { flex: 1; }
.faq-list_item { border-bottom: 1px solid var(--border-strong); border-radius: 0px; background-color: transparent; }
.faq-list_icon { flex: none; font-family: var(--font-display); font-size: 2.25rem; line-height: 1; color: var(--accent-default); }
@media screen and (max-width: 991px) { .faq-list_component { flex-direction: column; align-items: stretch; gap: 3rem; } }
@media screen and (max-width: 991px) { .faq-list_header { width: auto; } }
